// Shape of src/data/cases/<project>.json (generated by tools/build_cases.py)
export type Run = { text: string; fam: string; w: number; it: boolean; size: number; color: string };
export type Line = { x: number; base: number; runs: Run[] };
export type Para = { runs: Run[]; card: number | null; x: number; y: number; x1: number; size: number; align: "left" | "center" };
export type Card = { fill: string; op: number; x: number; y: number; w: number; h: number };
export type FrameImage = { x: number; y: number; w: number; h: number; src: string; ar: number; card: number | null };
export type CaseFrameData = {
  id: string; h: number; visual: boolean; bg: string; title: string;
  lines: Line[]; paras: Para[]; cards: Card[]; images: FrameImage[];
  links: [string, string][]; baked: string[];
};
export type CaseData = { slug: string; frames: CaseFrameData[] };
